import { BaseException } from '@game-studio/exceptions';
import { Locale } from '../../types';

export class PooledMemberOfLinkedListException extends BaseException {
    constructor() {
        super('PooledMemberOfLinkedListException', 'Node supplied is a member of the node pool');
    }

    public localise(locale: Locale): void {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
